 "content": "def transform(grid):
    # Horizontal/vertical repeating tile lattice. Each output cell is the
    # non-background value at the tile's upper-left corner, else the base.
    h, w = len(grid), len(grid[0])
    vals = {}
    for row in grid:
        for x in row:
            vals[x] = vals.get(x, 0) + 1
    base = max(vals, key=vals.get)
    # Marker/intersection rows and columns are identified by periodic rails;
    # locate them as rows/columns that differ from the uniform interior.
    rs = [r for r in range(h) if any(x != base for x in grid[r])]
    cs = [c for c in range(w) if any(grid[r][c] != base for r in range(h))]
    # Reduce a tile lattice by sampling one distinguished cell per tile.
    # Period is the distance between recurring rail positions.
    def runs(indices):
        out=[]
        for i in indices:
            if not out or i-out[-1][-1] > 1: out.append([i])
            else: out[-1].append(i)
        return [x[0] for x in out]
    rpos, cpos = runs(rs), runs(cs)
    return [[grid[r][c] for c in cpos] for r in rpos]
